// Darts — the second game, on the Darts tab. Reuses today's Spectrum puzzle data: the two least
// alike of its four spectrums become the board's axes (build.py picks them). Each round sets a
// fresh target, with rings around it worth points; one word is thrown at each. At the end the
// words that would have hit each target are revealed.
// The board is drawn as SVG over a pixel-art saloon scene (assets/, generated by art/*.py); a
// pixel-art cowboy in the foreground throws an animated dart at it.
// Everything lives in one closure so nothing collides with game.js.
(() => {
const ROUNDS = 4;
const SHARDS = 256;
const FIT_THRESHOLD = 25;    // same leniency as Spectrum
const RINGS = [[0.1, 50], [0.2, 25], [0.3, 10], [0.42, 5]]; // [radius in units, points], bull first
const MIN_R = 0.3, MAX_R = 0.75;  // the quarter targets sit in this band, clear of the centre bull
const REACH = 0.2;            // a target must have a common word inside its 25-point ring
const C = 300, R = 215;       // board centre and the screen length of one unit, in SVG units
const GRID = 0.25;            // matrix spacing, in units
const LABEL_GAP = 12;         // axis words sit this far inside the rim

// Scene geometry, in art pixels (the scene is 240x300; the board disc is radius 70 at (120,128)).
const SCENE = { w: 240, h: 300, cx: 120, cy: 128, r: 70 };
const THROWER = { x: 0, y: 190, w: 96, h: 110, frames: 6, hand: [87, 39], frameMs: 70, releaseFrame: 3 }; // hand = where the dart leaves, within a frame
const unitPx = SCENE.r;       // art pixels per board unit
const svgPerArt = (2 * R) / (2 * SCENE.r); // SVG units per art pixel

// ---- Themes: the same game in two rooms. Colours match art/PALETTE-*.md; sprites live in assets/<theme>/ ----
const THEMES = {
  saloon: {
    title: 'Darts', go: 'Throw', next: 'Next target', again: 'New targets', target: 'red target', miss: 'Missed.', landed: 'where your word landed',
    assets: 'assets/saloon', marker: 'dart-stuck.png', sweep: false, shots: 'darts',
    // board colours: disc, faint grid, main axes, live-ring fills bull outward, ring edge, ring text, past-target, past-target text, answer dot, leader line
    disc: '#2a1710', grid: '#5a2f1a', axis: '#f3e2b4', rings: ['#8e1d1d', '#c8322e', '#e07070', '#e9a0a0'], ringEdge: '#15090a', ringText: '#f3e2b4', ringTextBull: '#f3e2b4',
    past: '#5a2a3a', pastText: '#c9a46a', answer: '#ffb347', leader: '#f3e2b4', ink: '#15090a',
    actor: { frames: 6, frameMs: 70 }, animate: (...a) => animateDart(...a),
  },
  sonar: { // a full-screen command console; the board is a scope, pings instead of darts, no character
    title: 'Sonar', go: 'Ping', next: 'Next target', again: 'New targets', target: 'target', miss: 'No return.', landed: 'return plotted',
    assets: null, marker: null, sweep: true, console: true, terminal: true, shots: 'pings',
    disc: '#061a10', grid: '#0b3a22', axis: '#1f8a4d', rings: ['#c8ffd9', '#5ff29a', '#1f8a4d', '#0b3a22'], ringEdge: '#04110a', ringText: '#c8ffd9', ringTextBull: '#04110a',
    past: '#1f8a4d', pastText: '#5ff29a', answer: '#ffb84a', leader: '#5ff29a', ink: '#04110a',
    actor: null, animate: (...a) => animatePing(...a),
  },
};
let theme = THEMES.saloon;

// ---- Scoring: the one place to change the rule ----
// A dart scores the points of the innermost ring it lands in; the game's score is the total.
const scoreDart = d => (RINGS.find(([r]) => d <= r) || [0, 0])[1];
const total = ts => ts.reduce((s, t) => s + t.score, 0);
const MAX_SCORE = ROUNDS * RINGS[0][1];

// ---- State ----
let puzzle;               // today's Spectrum puzzle: {id, category, spectrums, board, common, date, number}
let axes = [0, 1];        // which of the puzzle's spectrums run left→right and bottom→top
let targets = [];         // one {x, y} per round
let throws = [];          // {word, x, y, d, score}, throw k was at targets[k]
let started = false, over = false, practice = false;
let awaiting = false;     // a dart has landed on the current target; the next target waits for a click
let throwing = false;     // the throw animation is playing
const shardCache = new Map();

const $ = id => document.getElementById(id);
const svg = $('d-board');
const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;');
const normalise = s => s.trim().toLowerCase().replace(/[^a-z\s-]/g, '').replace(/[\s-]+/g, ' ').trim();
const sx = x => C + x * R, sy = y => C - y * R;   // units → SVG
const round = () => throws.length - (awaiting || throwing ? 1 : 0); // index of the target on the board
const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
const bearing = p => String(Math.round(((Math.atan2(p.x, p.y) * 180 / Math.PI) + 360) % 360)).padStart(3, '0') + '°'; // 0 = up, clockwise
const range = p => Math.hypot(p.x, p.y).toFixed(2);
const brgRng = p => `BRG ${bearing(p)} RNG ${range(p)}`;

// ---- Seeded random: everyone gets the same targets on the same day ----
function fnv1a(s) {
  let h = 0x811c9dc5;
  for (const b of new TextEncoder().encode(s)) h = Math.imul(h ^ b, 0x01000193) >>> 0;
  return h;
}
function mulberry32(a) {
  return () => {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// The common category words, placed on the board.
const commonWords = () => Object.entries(puzzle.common || {}).map(([word, p]) => ({ word, x: p[axes[0]] / 100, y: p[axes[1]] / 100 }));

// One target per round. The first rounds each land in a different quarter of the board (in a random
// order) so that between them they explore the whole map; a target is only kept if a common word can
// score 25 on it. The last round is always the bull at the very centre of the board.
function makeTargets(rand) {
  const quarters = [0, 1, 2, 3];
  for (let i = 3; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [quarters[i], quarters[j]] = [quarters[j], quarters[i]]; }
  const words = commonWords();
  const ts = quarters.slice(0, ROUNDS - 1).map(qd => {
    let best = null;
    for (let tries = 0; tries < 40; tries++) {
      const ang = (qd + 0.1 + 0.8 * rand()) * Math.PI / 2;
      const r = Math.sqrt(MIN_R ** 2 + (MAX_R ** 2 - MIN_R ** 2) * rand());
      const t = { x: Math.round(100 * r * Math.cos(ang)) / 100, y: Math.round(100 * r * Math.sin(ang)) / 100 };
      const near = words.length ? Math.min(...words.map(w => dist(w, t))) : 0;
      if (!best || near < best.near) best = { t, near };
      if (near <= REACH) break;
    }
    return best.t;
  });
  ts.push({ x: 0, y: 0 });
  return ts;
}

// ---- Word lookup (same shard files as Spectrum) ----
async function shard(word) {
  const key = (fnv1a(word) % SHARDS).toString(16).padStart(2, '0');
  if (!shardCache.has(key)) shardCache.set(key, fetch(`puzzles/${puzzle.id}/w/${key}.json`).then(r => r.ok ? r.json() : {}));
  return shardCache.get(key);
}
async function lookup(word) {
  const parts = word.split(' ');
  const entries = await Promise.all(parts.map(async p => (await shard(p))[p]));
  if (entries.some(e => !e)) return null;
  const at = i => entries.reduce((s, e) => s + e[i], 0) / entries.length / 100;
  return { x: at(axes[0]), y: at(axes[1]), fit: Math.min(...entries.map(e => e[4])) };
}

// ---- Board ----
// A target: rings worth points, numbered. `live` draws it in full with point labels; otherwise faded.
function targetSvg(t, n, live) {
  const x = sx(t.x), y = sy(t.y);
  if (theme.console) return consoleTargetSvg(x, y, n, live);
  if (!live) { // a past target: just its bull, its outer ring and its round number
    return `<circle cx="${x}" cy="${y}" r="${RINGS[RINGS.length - 1][0] * R}" fill="none" stroke="${theme.past}" stroke-width="3" stroke-dasharray="6 8"/>` +
           `<circle cx="${x}" cy="${y}" r="${RINGS[0][0] * R}" fill="${theme.past}"/>` +
           `<text x="${x}" y="${y + 6}" font-size="18" fill="${theme.pastText}" text-anchor="middle">${n}</text>`;
  }
  let s = '';
  [...RINGS].reverse().forEach(([r, pts], k) => {
    const i = RINGS.length - 1 - k; // ring index, bull = 0
    s += `<circle cx="${x}" cy="${y}" r="${r * R}" fill="${theme.rings[i]}" stroke="${theme.ringEdge}" stroke-width="2"/>`;
    if (i > 0) { // points sit in each band, up the right-hand diagonal
      const rr = (r + RINGS[i - 1][0]) / 2 * R;
      s += `<text x="${x + rr * 0.72}" y="${y - rr * 0.72 + 6}" font-size="19" fill="${theme.ringText}" text-anchor="middle" paint-order="stroke" stroke="${theme.ink}" stroke-width="3">${pts}</text>`;
    }
  });
  s += `<text x="${x}" y="${y + 7}" font-size="22" font-weight="700" fill="${theme.ringTextBull}" text-anchor="middle" paint-order="stroke" stroke="${theme.ringTextBull === theme.ink ? 'none' : theme.ink}" stroke-width="3">${RINGS[0][1]}</text>`;
  return s;
}

// The scope's target: thin rings that leave the grid visible, point values up the top of each band,
// a bright bull with a halo, and a pulse that runs out from the bull (the stylesheet animates it).
function consoleTargetSvg(x, y, n, live) {
  const outer = RINGS[RINGS.length - 1][0] * R, bull = RINGS[0][0] * R;
  if (!live) {
    return `<g class="target past"><circle cx="${x}" cy="${y}" r="${outer}" fill="none" stroke="#1f8a4d" stroke-width="1" stroke-dasharray="3 7" opacity="0.7"/>` +
           `<circle cx="${x}" cy="${y}" r="${bull * 0.45}" fill="#1f8a4d" opacity="0.8"/>` +
           `<text x="${x}" y="${y - bull - 6}" font-size="14" fill="#1f8a4d" text-anchor="middle">${n}</text></g>`;
  }
  let s = `<g class="target live"><circle class="pulse" cx="${x}" cy="${y}" r="${outer}" fill="none" stroke="#5ff29a" stroke-width="2"/>`;
  RINGS.forEach(([r, pts], i) => {
    const rr = r * R, bright = i === 0;
    s += `<circle cx="${x}" cy="${y}" r="${rr}" fill="${bright ? '#5ff29a' : 'none'}" fill-opacity="0.12" stroke="${bright ? '#c8ffd9' : '#5ff29a'}" stroke-width="${bright ? 2 : 1.2}" stroke-dasharray="${i === RINGS.length - 1 ? '6 5' : 'none'}" opacity="${bright ? 1 : 0.85 - i * 0.15}"/>`;
    // the band's value, just inside its top edge
    s += `<text x="${x}" y="${y - rr + 14}" font-size="12" fill="#c8ffd9" text-anchor="middle" opacity="0.9">${pts}</text>`;
  });
  // crosshair ticks and the bull
  for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) s += `<line x1="${x + dx * bull * 1.3}" y1="${y + dy * bull * 1.3}" x2="${x + dx * bull * 2.1}" y2="${y + dy * bull * 2.1}" stroke="#c8ffd9" stroke-width="1.2" opacity="0.8"/>`;
  s += `<circle class="bull" cx="${x}" cy="${y}" r="${bull * 0.42}" fill="#c8ffd9"/>`;
  s += `<text x="${x}" y="${y + bull + 16}" font-size="12" fill="#c8ffd9" text-anchor="middle" letter-spacing="2">T${n}</text></g>`;
  return s;
}

// A dart stuck in the board (or a blip on the scope): the theme's pixel sprite, drawn to scale.
function stuckDart(x, y, faded) {
  if (!theme.marker) { // a sonar return: a bright dot in a thin ring
    return `<g opacity="${faded ? 0.6 : 1}"><circle cx="${x}" cy="${y}" r="11" fill="none" stroke="#5ff29a" stroke-width="1.5"/>` +
           `<circle cx="${x}" cy="${y}" r="4.5" fill="#c8ffd9"/></g>`;
  }
  const w = 12 * svgPerArt;
  return `<image href="${theme.assets}/${theme.marker}" x="${x - w / 2}" y="${y - w / 2}" width="${w}" height="${w}" style="image-rendering:pixelated" opacity="${faded ? 0.55 : 1}"/>`;
}

// The console scope's furniture: a bearing ring with ticks and headings, and readouts in the corners.
function consoleSvg() {
  let s = `<circle cx="${C}" cy="${C}" r="${R + 3}" fill="none" stroke="#1f8a4d" stroke-width="1.5"/>`;
  for (let d = 0; d < 360; d += 5) {
    const a = d * Math.PI / 180, major = d % 30 === 0, len = major ? 14 : d % 10 === 0 ? 9 : 5;
    s += `<line x1="${C + (R + 6) * Math.sin(a)}" y1="${C - (R + 6) * Math.cos(a)}" x2="${C + (R + 6 + len) * Math.sin(a)}" y2="${C - (R + 6 + len) * Math.cos(a)}" stroke="${major ? '#5ff29a' : '#1f8a4d'}" stroke-width="${major ? 2 : 1}"/>`;
    if (major) s += `<text class="bearing" x="${C + (R + 36) * Math.sin(a)}" y="${C - (R + 36) * Math.cos(a) + 5}" text-anchor="middle">${String(d).padStart(3, '0')}</text>`;
  }
  const tg = targets[Math.min(round(), ROUNDS - 1)], sum = total(throws);
  s += `<text class="corner" x="14" y="26">${over ? 'All targets resolved' : 'Active sonar'}</text><text class="corner" x="14" y="48">Rng scale 1.00</text>`;
  s += `<text class="corner" x="586" y="26" text-anchor="end">${over ? 'Standby' : `Target ${round() + 1}`}</text><text class="corner" x="586" y="48" text-anchor="end">${over ? '' : brgRng(tg)}</text>`;
  s += `<text class="corner" x="14" y="586">Round ${Math.min(round() + 1, ROUNDS)}/${ROUNDS}</text>`;
  s += `<text class="corner" x="586" y="586" text-anchor="end">Score ${sum}/${MAX_SCORE}</text>`;
  return s;
}

// The sonar sweep: a fading wedge that the stylesheet spins around the scope.
function sweepSvg() {
  let s = '<g class="sweep">';
  for (let k = 0; k < 8; k++) {
    const a0 = -k * 7 * Math.PI / 180, a1 = -(k + 1) * 7 * Math.PI / 180;
    s += `<path d="M${C},${C} L${C + R * Math.sin(a0)},${C - R * Math.cos(a0)} A${R},${R} 0 0 0 ${C + R * Math.sin(a1)},${C - R * Math.cos(a1)} Z" fill="#27a85e" opacity="${0.42 * (1 - k / 8)}"/>`;
  }
  s += `<line x1="${C}" y1="${C}" x2="${C}" y2="${C - R}" stroke="#c8ffd9" stroke-width="3" opacity="0.9"/></g>`;
  return s;
}

function render() {
  if (!puzzle) return;
  const [X, Y] = axes.map(i => puzzle.spectrums[i]);
  let s = `<defs><clipPath id="d-clip"><circle cx="${C}" cy="${C}" r="${R}"/></clipPath>` +
          `<radialGradient id="d-glass"><stop offset="0" stop-color="#0d3a22"/><stop offset="0.7" stop-color="${theme.disc}"/><stop offset="1" stop-color="#030b07"/></radialGradient></defs>`;
  s += `<circle cx="${C}" cy="${C}" r="${R}" fill="${theme.console ? 'url(#d-glass)' : theme.disc}"/>`;
  if (theme.console) s += consoleSvg();
  // The matrix: grid lines every GRID units, clipped to the board; the two axes through the centre stand out.
  s += '<g clip-path="url(#d-clip)">';
  if (theme.sweep) { // range rings behind everything, then the sweep
    for (const f of [0.25, 0.5, 0.75]) s += `<circle cx="${C}" cy="${C}" r="${R * f}" fill="none" stroke="${theme.grid}" stroke-width="2"/>`;
    s += sweepSvg();
  }
  for (let v = -1; v <= 1.001; v += GRID) {
    const main = Math.abs(v) < 1e-9, col = main ? theme.axis : theme.grid, w = main ? 3 : 2;
    s += `<line x1="${sx(v)}" y1="${sy(-1)}" x2="${sx(v)}" y2="${sy(1)}" stroke="${col}" stroke-width="${w}"/>`;
    s += `<line x1="${sx(-1)}" y1="${sy(v)}" x2="${sx(1)}" y2="${sy(v)}" stroke="${col}" stroke-width="${w}"/>`;
  }
  if (started) {
    targets.forEach((t, k) => { if (k < round() || over) s += targetSvg(t, k + 1, false); });
    if (!over) s += targetSvg(targets[round()], round() + 1, true);
  }
  // Axis end words, just inside the rim at the end of each axis, like a compass rose.
  s += `<text class="axis" x="${sx(-1) + LABEL_GAP}" y="${C - 10}" text-anchor="start">${esc(X.low)}</text>`;
  s += `<text class="axis" x="${sx(1) - LABEL_GAP}" y="${C - 10}" text-anchor="end">${esc(X.high)}</text>`;
  s += `<text class="axis" x="${C}" y="${sy(1) + 42}" text-anchor="middle">${esc(Y.high)}</text>`;
  s += `<text class="axis" x="${C}" y="${sy(-1) - 28}" text-anchor="middle">${esc(Y.low)}</text>`;
  s += '</g>';
  if (!started) { svg.innerHTML = s; renderSide(); return; }
  // Darts: the newest is tied to its target with a dashed line while it sits on it.
  const labels = [];
  throws.forEach((t, k) => {
    if (k === throws.length - 1 && throwing) return; // still in the air
    const x = sx(t.x), y = sy(t.y), last = k === throws.length - 1, tg = targets[k];
    if (last && awaiting) s += `<line x1="${x}" y1="${y}" x2="${sx(tg.x)}" y2="${sy(tg.y)}" stroke="${theme.leader}" stroke-width="2" stroke-dasharray="4 6"/>`;
    s += stuckDart(x, y, !last || over);
    labels.push({ x, y, word: t.word, cls: 'tag' });
  });
  // At the end, the best word for each target is shown where it sits.
  if (over) for (const a of answers()) if (a.best && !throws.some(t => t.word === a.best.word)) labels.push({ x: sx(a.best.x), y: sy(a.best.y), word: a.best.word, cls: 'tag ans', dot: true });
  for (const l of labels) if (l.dot) s += `<circle cx="${l.x}" cy="${l.y}" r="6" fill="${theme.answer}" stroke="${theme.ink}" stroke-width="2"/>`;
  // Words beside their darts: to the right unless near the right edge; pushed down when they'd overlap.
  for (const l of labels) {
    const right = l.x < C + R * 0.55, w = (l.word.length + 2) * 11;
    l.tx = right ? l.x + 16 : l.x - 16; l.anchor = right ? 'start' : 'end'; l.ty = l.y + 7;
    l.x0 = right ? l.tx : l.tx - w; l.x1 = l.x0 + w;
  }
  for (let pass = 0; pass < 4; pass++) for (let a = 0; a < labels.length; a++) for (let b = a + 1; b < labels.length; b++) {
    const A = labels[a], B = labels[b];
    if (A.x0 < B.x1 && B.x0 < A.x1 && Math.abs(A.ty - B.ty) < 22) B.ty = A.ty + 22;
  }
  for (const l of labels) s += `<text class="${l.cls}" x="${l.tx}" y="${l.ty}" text-anchor="${l.anchor}">${esc(l.word)}</text>`;
  svg.innerHTML = s;
  renderSide();
  $('d-legend').textContent = over
    ? `Your ${theme.shots}, and the words that would have scored most on each ${theme.target}${practice ? ' · practice' : ''}`
    : awaiting ? `Round ${round() + 1} of ${ROUNDS} · ${theme.landed}${practice ? ' · practice' : ''}`
    : `Round ${round() + 1} of ${ROUNDS} · ${theme.go.toLowerCase()} a word at the ${theme.target}${practice ? ' · practice' : ''}`;
}

// ---- The throw. Saloon: the cowboy winds up and a dart flies from his hand to where the word lands.
// Sonar: the operator presses the ping button, a pulse spreads from the centre and the word echoes back as a blip. ----
const stage = $('d-stage'), actor = $('d-actor'), dart = $('d-dart'), ping = $('d-ping'), flash = $('d-flash');
const pxScale = () => stage.clientWidth / SCENE.w; // screen pixels per art pixel
function fitStage() { document.documentElement.style.setProperty('--px', pxScale()); }
new ResizeObserver(fitStage).observe(stage);
fitStage();

const sleep = ms => new Promise(r => setTimeout(r, ms));
function setFrame(i) { if (theme.actor) actor.style.backgroundPosition = `calc(var(--px) * ${-i * THROWER.w}px) 0`; }
const landingPx = (landing, k) => [(SCENE.cx + landing.x * unitPx) * k, (SCENE.cy - landing.y * unitPx) * k];

async function animateDart(landing) { // landing in board units
  const k = pxScale(), ms = theme.actor.frameMs;
  const from = [(THROWER.x + THROWER.hand[0]) * k, (THROWER.y + THROWER.hand[1]) * k];
  const to = landingPx(landing, k);
  for (let f = 0; f < THROWER.releaseFrame; f++) { setFrame(f); await sleep(ms); }
  setFrame(THROWER.releaseFrame);
  const size = 16 * k, ang = Math.atan2(to[1] - from[1], to[0] - from[0]) * 180 / Math.PI + 45; // the sprite points up-right
  dart.style.display = 'block';
  const lift = 14 * k, mid = [(from[0] + to[0]) / 2, (from[1] + to[1]) / 2 - lift];
  const flight = dart.animate([
    { transform: `translate(${from[0] - size / 2}px, ${from[1] - size / 2}px) rotate(${ang}deg) scale(1.15)` },
    { transform: `translate(${mid[0] - size / 2}px, ${mid[1] - size / 2}px) rotate(${ang}deg) scale(0.95)`, offset: 0.5 },
    { transform: `translate(${to[0] - size / 2}px, ${to[1] - size / 2}px) rotate(${ang}deg) scale(0.6)` },
  ], { duration: 460, easing: 'ease-in', fill: 'forwards' });
  const rest = (async () => { for (let f = THROWER.releaseFrame + 1; f < theme.actor.frames; f++) { await sleep(ms * 1.6); setFrame(f); } })();
  await flight.finished;
  dart.style.display = 'none';
  stage.classList.remove('thunk'); void stage.offsetWidth; stage.classList.add('thunk');
  await rest;
  setFrame(0);
}

async function animatePing(landing) {
  // On the console the scope fills the stage: its centre is the stage's centre and the disc spans R of the 600 box.
  const sw = stage.clientWidth, cx = sw / 2, cy = sw / 2, rim = sw * R / 600;
  msg('Pinging…', '#5ff29a');
  await sleep(120);
  const reach = Math.min(1.45, Math.max(0.15, Math.hypot(landing.x, landing.y))); // the pulse runs out to the word, at least a little way
  const dur = 350 + 450 * reach;
  ping.style.display = 'block';
  const pulse = ping.animate([
    { left: `${cx}px`, top: `${cy}px`, width: '0px', height: '0px', opacity: 1 },
    { left: `${cx - rim * reach}px`, top: `${cy - rim * reach}px`, width: `${2 * rim * reach}px`, height: `${2 * rim * reach}px`, opacity: 0.15 },
  ], { duration: dur, easing: 'linear', fill: 'forwards' });
  await pulse.finished;
  ping.style.display = 'none';
  const lx = cx + landing.x * rim, ly = cy - landing.y * rim, fs = sw * 0.06; // the echo: a flash where the word is
  flash.style.display = 'block';
  await flash.animate([
    { left: `${lx - fs / 2}px`, top: `${ly - fs / 2}px`, width: `${fs}px`, height: `${fs}px`, opacity: 1 },
    { left: `${lx - fs / 8}px`, top: `${ly - fs / 8}px`, width: `${fs / 4}px`, height: `${fs / 4}px`, opacity: 0 },
  ], { duration: 320, easing: 'ease-out', fill: 'forwards' }).finished;
  flash.style.display = 'none';
  msg('');
}

// ---- Theme switch ----
function applyTheme(name) {
  theme = THEMES[name] || THEMES.saloon;
  document.body.dataset.theme = theme === THEMES.sonar ? 'sonar' : 'saloon';
  for (const b of document.querySelectorAll('.themes button')) b.setAttribute('aria-pressed', String(THEMES[b.dataset.theme] === theme));
  if (document.body.dataset.tab === 'darts') { $('title').textContent = theme.title; document.title = theme.title; }
  $('d-go').textContent = theme.go; $('d-submit').textContent = theme.go; $('d-next').textContent = theme.next; $('d-again').textContent = theme.again;
  setFrame(0);
  try { localStorage.setItem('darts:theme', document.body.dataset.theme); } catch {}
  if (theme.terminal && puzzle && !started) start(); // the console has no start step
  render();
}
window.dartsApplyTheme = () => applyTheme(document.body.dataset.theme);
for (const b of document.querySelectorAll('.themes button')) b.addEventListener('click', () => applyTheme(b.dataset.theme));
{
  let initial = new URLSearchParams(location.search).get('theme');
  if (!initial) { try { initial = localStorage.getItem('darts:theme'); } catch {} }
  applyTheme(initial || 'saloon');
}

// ---- Readout ----
function hint(t, tg) {
  if (t.d <= RINGS[0][0]) return 'bullseye!';
  const parts = [];
  axes.forEach((i, k) => {
    const gap = k === 0 ? t.x - tg.x : t.y - tg.y;
    if (Math.abs(gap) < 0.12) return;
    const sp = puzzle.spectrums[i];
    parts.push(`${Math.abs(gap) > 0.6 ? 'much ' : ''}more ${sp[gap > 0 ? 'low' : 'high']}`);
  });
  const off = Math.hypot(t.x, t.y) > 1 ? 'off the board — ' : '';
  return off + (parts.length ? `needed ${parts.join(', ')}` : 'so close') + '.';
}
function renderReadout() {
  $('d-readout').innerHTML = throws.map((t, k) =>
    `<li><span class="n">${k + 1}</span><span class="w">${esc(t.word)}</span><span class="s">${t.score}</span><span class="brg">${brgRng(t)}</span><span class="hint">${hint(t, targets[k])}</span></li>`).join('');
}

// The console's other screens: the status strip in the head, and the analysis screen (latest return, axis bars).
function renderSide() {
  if (!theme.console || !puzzle) return;
  const cur = over ? -1 : round(), last = throws[throws.length - 1], sum = total(throws);
  $('d-status').textContent = over ? `Final ${sum} / ${MAX_SCORE}` : `Round ${Math.min(cur + 1, ROUNDS)} of ${ROUNDS} · Score ${sum} / ${MAX_SCORE}`;
  $('d-rounds').innerHTML = targets.map((t, k) => {
    const th = throws[k], cls = k === cur ? 'cur' : th ? 'done' : '';
    const status = th ? `${esc(th.word)} · ${th.score} pts` : k === cur ? (awaiting ? 'plotted' : 'tracking') : 'standby';
    return `<li class="${cls}"><span>Target ${k + 1}</span><span>${status}</span></li>`;
  }).join('');
  const best = throws.reduce((a, b) => !a || b.score > a.score ? b : a, null);
  $('d-score').innerHTML = `<dt>Round</dt><dd>${Math.min(over ? ROUNDS : cur + 1, ROUNDS)} / ${ROUNDS}</dd><dt>Score</dt><dd>${sum} / ${MAX_SCORE}</dd>` +
    `<dt>Bullseyes</dt><dd>${throws.filter(t => t.score === RINGS[0][1]).length}</dd><dt>Best</dt><dd>${best ? `${esc(best.word)} ${best.score}` : '—'}</dd>`;
  const tg = targets[Math.min(cur < 0 ? ROUNDS - 1 : cur, ROUNDS - 1)];
  $('d-detail').innerHTML = over ? `All ${ROUNDS} targets resolved. Final score <b>${sum}</b> of ${MAX_SCORE}.`
    : awaiting ? `Target ${throws.length} · <b>${esc(last.word)}</b>\n${brgRng(last)} · <b>${last.score} pts</b>\n${hint(last, targets[throws.length - 1])}`
    : `Target ${cur + 1} · ${brgRng(tg)}${last ? `\nLast ping <b>${esc(last.word)}</b> · ${last.score} pts` : '\nNo pings yet.'}`;
  // Axis analysis: each spectrum as a bar, the target hollow, the latest word solid.
  const L = 70, Rr = 230, rows = axes.map((i, k) => {
    const sp = puzzle.spectrums[i], y = 30 + k * 46, px = v => L + (v + 1) / 2 * (Rr - L);
    const tv = k === 0 ? tg.x : tg.y, wv = last ? (k === 0 ? last.x : last.y) : null;
    let r = `<text x="${L - 8}" y="${y + 4}" text-anchor="end" font-size="11" fill="#5ff29a">${esc(sp.low.toUpperCase())}</text>` +
            `<text x="${Rr + 8}" y="${y + 4}" font-size="11" fill="#5ff29a">${esc(sp.high.toUpperCase())}</text>` +
            `<line x1="${L}" y1="${y}" x2="${Rr}" y2="${y}" stroke="#1f8a4d" stroke-width="1"/>`;
    for (const v of [-1, -0.5, 0, 0.5, 1]) r += `<line x1="${px(v)}" y1="${y - 4}" x2="${px(v)}" y2="${y + 4}" stroke="#1f8a4d"/>`;
    r += `<circle cx="${px(tv)}" cy="${y}" r="6" fill="none" stroke="#c8ffd9" stroke-width="1.5"/>`;
    if (wv !== null) {
      const cl = Math.max(-1.1, Math.min(1.1, wv));
      r += `<circle cx="${px(cl)}" cy="${y}" r="4" fill="#5ff29a"/>` +
           `<text x="${(px(tv) + px(cl)) / 2}" y="${y + 19}" text-anchor="middle" font-size="11" fill="#ffb84a">${Math.abs(wv - tv) < 0.12 ? 'ON' : `${wv > tv ? '+' : '−'}${Math.abs(wv - tv).toFixed(2)}`}</text>`;
    }
    return r;
  });
  $('d-axes').innerHTML = rows.join('') + `<text x="150" y="104" text-anchor="middle" font-size="10" fill="#1f8a4d">○ TARGET   ● YOUR WORD</text>`;
}

// For each round: the common words that would have scored, best first (at most four shown).
function answers() {
  const words = commonWords();
  return targets.map(tg => {
    const hits = words.map(w => ({ ...w, d: dist(w, tg), score: scoreDart(dist(w, tg)) }))
      .filter(w => w.score > 0).sort((a, b) => a.d - b.d);
    return { hits: hits.slice(0, 4), best: hits[0] };
  });
}

// ---- Game flow ----
function msg(text, colour) { $('d-message').textContent = text; $('d-message').style.color = colour || ''; }

function start() {
  started = true;
  $('d-start').hidden = true;
  $('d-form').hidden = false;
  render();
  $('d-guess').focus();
  save();
}

async function submitThrow(e) {
  e.preventDefault();
  if (over || throwing) return;
  if (awaiting && theme.terminal) return nextTarget(); // Enter again moves on to the next target
  const word = normalise($('d-guess').value);
  if (!word) return;
  if (throws.some(t => t.word === word)) return msg(`You already threw "${word}".`);
  $('d-submit').disabled = true;
  const entry = await lookup(word);
  $('d-submit').disabled = false;
  if (!entry) return msg(`"${word}" isn't a word I know.`);
  if (entry.fit < FIT_THRESHOLD) return msg(`"${word}" doesn't look like ${puzzle.category.toLowerCase()} to me — try another word.`);
  $('d-guess').value = '';
  msg('');
  await addThrow(word, entry, true);
  save();
}

async function addThrow(word, entry, animate) {
  const tg = targets[round()];
  const d = dist(entry, tg), score = scoreDart(d);
  throws.push({ word, x: entry.x, y: entry.y, d, score });
  if (animate) {
    throwing = true;
    $('d-form').hidden = true;
    render();
    await theme.animate(entry);
    throwing = false;
  }
  renderReadout();
  if (throws.length === ROUNDS) return endGame();
  awaiting = true;
  if (theme.terminal) { // the terminal stays up: the result prints, Enter moves on
    $('d-form').hidden = false;
    msg(`${word} · ${score ? `${score} points` : 'no points'} · ${hint(throws[throws.length - 1], tg)}  Press Enter for target ${throws.length + 1}.`);
    render();
    $('d-guess').focus();
    return;
  }
  msg(score ? `${score} points${score === RINGS[0][1] ? ' — bullseye!' : ''}.` : theme.miss);
  $('d-form').hidden = true;
  $('d-nextp').hidden = false;
  render();
  $('d-next').focus();
}

function nextTarget() {
  awaiting = false;
  msg('');
  $('d-nextp').hidden = true;
  $('d-form').hidden = false;
  render();
  $('d-guess').focus();
  save();
}

function endGame() {
  over = true; awaiting = false;
  document.body.classList.add('d-over');
  $('d-form').hidden = true;
  $('d-nextp').hidden = true;
  msg('');
  const sum = total(throws), bulls = throws.filter(t => t.score === RINGS[0][1]).length;
  $('d-result').textContent = `Score ${sum} of ${MAX_SCORE}${bulls ? `, with ${bulls} bullseye${bulls > 1 ? 's' : ''}` : ''}.`;
  $('d-share-text').textContent = `Darts #${puzzle.number} · ${sum}/${MAX_SCORE} · ${throws.map(t => t.score).join(' ')}`;
  $('d-share').hidden = false;
  $('d-reveal').innerHTML = answers().map((a, k) => {
    const you = throws[k];
    const list = a.hits.length ? a.hits.map(h => `${esc(h.word)} <span class="s">${h.score}</span>`).join(', ') : 'no common word scores here';
    return `<li><span class="n">${k + 1}</span><span class="hint">you threw <b>${esc(you.word)}</b> for ${you.score} · best: ${list}</span></li>`;
  }).join('');
  $('d-reveal-wrap').hidden = false;
  render();
}

// Fresh, unseeded targets on the same board for another go. Practice games aren't saved.
function again() {
  practice = true; over = false; awaiting = false; throws = [];
  document.body.classList.remove('d-over');
  targets = makeTargets(Math.random);
  $('d-nextp').hidden = true;
  $('d-readout').innerHTML = ''; $('d-result').textContent = ''; $('d-share').hidden = true; $('d-reveal-wrap').hidden = true;
  $('d-form').hidden = false;
  msg('');
  render();
  $('d-guess').focus();
}

// ---- Persistence ----
const key = () => `darts:${puzzle.id}:${puzzle.date}`;
function save() {
  if (practice) return;
  try { localStorage.setItem(key(), JSON.stringify({ started, words: throws.map(t => t.word), awaiting })); } catch {}
}
async function restore() {
  let saved;
  try { saved = JSON.parse(localStorage.getItem(key())); } catch {}
  if (!saved || !saved.started) return;
  start();
  for (const w of saved.words) {
    if (over) break;
    if (awaiting) nextTarget();
    const entry = await lookup(w);
    if (entry) await addThrow(w, entry, false);
  }
  if (awaiting && !saved.awaiting) nextTarget(); // they had already clicked on to the next target
  save();
}

// ---- Wiring ----
$('d-go').addEventListener('click', start);
$('d-form').addEventListener('submit', submitThrow);
$('d-again').addEventListener('click', again);
$('d-next').addEventListener('click', nextTarget);
$('d-copy').addEventListener('click', () => navigator.clipboard.writeText($('d-share-text').textContent).then(() => { $('d-copy').textContent = 'Copied'; }));

// ---- Load today's puzzle (same schedule as Spectrum) ----
(async () => {
  try {
    const index = await fetch('puzzles/index.json').then(r => r.json());
    const now = new Date();
    const date = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
    const params = new URLSearchParams(location.search);
    const id = params.get('puzzle') || index.days[date];
    if (!id) throw new Error(`no puzzle scheduled for ${date} — run build.py`);
    if (params.has('fresh')) { try { localStorage.removeItem(`darts:${id}:${date}`); } catch {} }
    puzzle = await fetch(`puzzles/${id}/puzzle.json`).then(r => r.json());
    puzzle.date = date;
    puzzle.number = Math.round((Date.parse(date) - Date.parse(index.launch)) / 864e5) + 1;
    axes = puzzle.board || [0, 1];
    targets = makeTargets(mulberry32(fnv1a(`darts:${id}:${date}`)));
    $('d-sub').textContent = `#${puzzle.number} · ${now.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'long' })} · ${puzzle.category}`;
    render();
    $('d-go').disabled = false;
    await restore();
    if (theme.terminal && !started) start();
  } catch (err) {
    $('d-sub').textContent = `Couldn't load today's board (${err.message}). Serve this folder over http.`;
  }
})();
})();
